import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"19、【临】 兑下坤上","description":"周易集注 - 19、【临】 兑下坤上","frontmatter":{"title":"19、【临】 兑下坤上","description":"周易集注 - 19、【临】 兑下坤上"},"headers":[],"relativePath":"zh/classics/jizhu/023.md","filePath":"zh/classics/jizhu/023.md"}'),l={name:"zh/classics/jizhu/023.md"};function h(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_19、【临】-兑下坤上" tabindex="-1">19、【临】 兑下坤上 <a class="header-anchor" href="#_19、【临】-兑下坤上" aria-label="Permalink to “19、【临】 兑下坤上”">​</a></h1><p>临者，进而临逼于阴也<em>。二阳浸长，以逼于阴，故为临，十二月之卦也。天下之物密近相临者，莫如地与水，故地上有水则为比，泽上有地</em>则为临。《序卦》“有事而后可大”，临者大也，蛊者事也。韩康伯云可大之业由事而生，二阳方长而盛大，所以次蛊。</p><ul><li><p>原文作“进而临逼于阳也”有误，据上下文义及卦气说之义理以修改。</p></li><li><p>原文作“泽上有水”有误，临卦为泽上有地。</p></li></ul><p>临综观，二卦同体，文王综为一卦，故《杂卦》曰“临观之义，或与或求”，言至建酉，则二阳又在上，阴又逼迫阳矣。至于八月，非临数，至观八个月也。言至建酉之月为观，见阴之消不久也。专以综卦言。</p><p>《彖》曰：临刚浸而长，说而顺，刚中而应，大亨以正，天之道也。至于八月有凶，消不久也。</p><p>以卦体卦德释卦名卦辞。浸者渐也，言自复一阳生至临则阳渐长矣，此释卦名。说而顺者，内说而外顺也。说则阳之进也不逼，顺则阴之从也不逆。刚中而应者，九二刚中，应乎六五之柔中也。言虽刚浸长，逼迫乎阴，然非倚刚之强暴而逼迫也，乃彼此和顺相应也，此言临有此善也。刚浸长而悦顺者，大亨也。刚中而应，柔中者以正也，天之道者，天道之自然也，言天道阳长阴消原是如此，大亨以正也。一诚通复，岂不大亨以正，故文王卦辞曰元亨利贞者此也。然阴之消，岂长消哉?至酉曰观，阴复长而凶矣。</p><h3 id="《象》曰-泽上有地-临-君子以教思无穷-容保民无疆。" tabindex="-1">《象》曰：泽上有地，临，君子以教思无穷，容保民无疆。 <a class="header-anchor" href="#《象》曰-泽上有地-临-君子以教思无穷-容保民无疆。" aria-label="Permalink to “《象》曰：泽上有地，临，君子以教思无穷，容保民无疆。”">​</a></h3><p>教者，劳来匡直之谓也。思者，教之至诚恻怛，出于心思也。无穷者，教之心思不至厌斁而穷尽也。容者，民皆在统驭之中也。保者，民皆得其所也。无疆者，无疆域之限也。无穷与兑泽同其渊深，无疆与坤土同其博大，二者皆临民之事，故君子观临民之象以之。</p><p>初九，咸临，贞吉。</p><p>咸，皆也，同也。以大临小者，初九，九二临乎四阴也。以上临下者，上三爻临乎其下也。彼临乎此，此临乎彼，皆同乎临。故曰咸临，卦惟二阳，故此二爻，皆称咸临。九刚而得正，故占者贞吉。</p><h3 id="《象》曰-咸临贞吉-志行正也。" tabindex="-1">《象》曰：咸临贞吉，志行正也。 <a class="header-anchor" href="#《象》曰-咸临贞吉-志行正也。" aria-label="Permalink to “《象》曰：咸临贞吉，志行正也。”">​</a></h3><p>初正应四亦正，故曰正。中爻震足，故初行五亦行。</p><p>九二，咸临，吉，无不利。</p><p>咸临与初同而占不同者，九二有刚中之德，而又有上进之势，所以吉无不利。</p><h3 id="《象》曰-咸临吉无不利-未顺命也。" tabindex="-1">《象》曰：咸临吉无不利，未顺命也。 <a class="header-anchor" href="#《象》曰-咸临吉无不利-未顺命也。" aria-label="Permalink to “《象》曰：咸临吉无不利，未顺命也。”">​</a></h3><p>未顺命者，未顺五之命也。五君位，故曰命，且兑综巽，亦有命字之象。本卦彖辞悦而顺，孔子恐人疑此爻之吉无不利者乃悦而顺五之命也，故于《小象》曰二之吉利者乃有刚中之德，阳势上进，所以吉利也，未顺五之命也。</p><p>六三，甘临，无攸利。既忧之，无咎。</p><p>甘临者，以甘悦人，而无实德也。坤土其味甘，兑为口，甘之象也，故节卦九五变临，亦曰甘。节无攸利者，不诚不能动物也。变干，干三爻，惕若，忧之象也。</p><p>三居下之上，临人者也。阴柔悦体，又不中正，故有以甘悦临人之象，此占者所以无攸利也。能忧而改之，斯无咎矣。</p><h3 id="《象》曰-甘临-位不当也。既忧之-咎不长也。" tabindex="-1">《象》曰：甘临，位不当也。既忧之，咎不长也。 <a class="header-anchor" href="#《象》曰-甘临-位不当也。既忧之-咎不长也。" aria-label="Permalink to “《象》曰：甘临，位不当也。既忧之，咎不长也。”">​</a></h3><p>位不当者，阴柔不中正也。咎不长者，改过也。</p><p>六四，至临，无咎。</p><p>六四当坤兑之交，地泽相比，盖临亲切之至者，所以占者无咎。</p><h3 id="《象》曰-至临无咎-位当也。" tabindex="-1">《象》曰：至临无咎，位当也。 <a class="header-anchor" href="#《象》曰-至临无咎-位当也。" aria-label="Permalink to “《象》曰：至临无咎，位当也。”">​</a></h3><p>以阴居阴，故位当。</p><p>六五，知临，大君之宜，吉。(知音智)</p><p>变坎，坎为通，智之象也。知临者，明四目，达四聪，不自用而任人也。应乾阳，故曰大君。知临之知，原生于九二，故即曰大君。知者觉也，智即知也。六五非九二不能至此宜者，得人君之统体也。</p><p>六五柔中居尊，下任九二刚中之贤，兼众智以临天下，盖得大君之宜者也，吉可知矣。占者有是德，亦如是占也。</p><h3 id="《象》曰-大君之宜-行中之谓也。" tabindex="-1">《象》曰：大君之宜，行中之谓也。 <a class="header-anchor" href="#《象》曰-大君之宜-行中之谓也。" aria-label="Permalink to “《象》曰：大君之宜，行中之谓也。”">​</a></h3><p>与初行正同，六五中，九二亦中，故曰行中，行中即用中。中爻震足，行之象也。</p><p>上六，敦临，吉，无咎。</p><p>敦，厚也。爻本坤土，又变艮土，敦厚之象。初与二虽非正应，然志在二阳，尊而应卑，高而从下，盖敦厚之至者。</p><p>上六居临之终，坤土敦厚，有敦临之象，吉而无咎之道也。故其象占如此。</p><h3 id="《象》曰-敦临之吉-志在内也。" tabindex="-1">《象》曰：敦临之吉，志在内也。 <a class="header-anchor" href="#《象》曰-敦临之吉-志在内也。" aria-label="Permalink to “《象》曰：敦临之吉，志在内也。”">​</a></h3><p>志在内卦二阳，曰志者，非正应也。</p>',35)])])}const m=e(l,[["render",h]]);export{_ as __pageData,m as default};
